// Имена компонентов и их пропсы взяты по документированному контракту value/onValueChange;
// точные сигнатуры JxInput/JxSelect/JxSwitch стоит сверить с типами пакета.
import { useState, type FormEvent } from 'react';
import { JxButton, JxInput, JxSelect, JxSwitch } from '@jinx-ui/react';

export type Language = 'ru' | 'en';

export type ProfileSettings = {
  name: string;
  language: Language;
  emailNotifications: boolean;
};

type ProfileSettingsFormProps = {
  initialSettings?: ProfileSettings;
  onSave: (settings: ProfileSettings) => void;
};

const LANGUAGE_OPTIONS: Array<{ value: Language; label: string }> = [
  { value: 'ru', label: 'Русский' },
  { value: 'en', label: 'English' },
];

export default function ProfileSettingsForm({
  initialSettings,
  onSave,
}: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialSettings?.name ?? '');
  const [language, setLanguage] = useState<Language>(initialSettings?.language ?? 'ru');
  const [emailNotifications, setEmailNotifications] = useState(
    initialSettings?.emailNotifications ?? false,
  );

  const trimmedName = name.trim();

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!trimmedName) return;
    onSave({ name: trimmedName, language, emailNotifications });
  };

  return (
    <form
      className="jx-stack"
      style={{ gap: 'var(--jx-space-4)', maxWidth: 'var(--jx-size-form-md)' }}
      onSubmit={handleSubmit}
      noValidate
    >
      <JxInput
        label="Имя"
        name="name"
        value={name}
        onValueChange={setName}
        placeholder="Как к вам обращаться"
        required
      />

      <JxSelect
        label="Язык интерфейса"
        name="language"
        value={language}
        onValueChange={(next: Language) => setLanguage(next)}
        options={LANGUAGE_OPTIONS}
      />

      <JxSwitch
        label="Уведомления на почту"
        name="emailNotifications"
        checked={emailNotifications}
        onCheckedChange={setEmailNotifications}
      />

      <JxButton type="submit" variant="primary" disabled={!trimmedName}>
        Сохранить
      </JxButton>
    </form>
  );
}

